xpath.script:
(function() {
    var header = document.getElementById('dimsop_header');
    var lastScroll = 0;
    var scrollThreshold = 80;

    window.addEventListener('scroll', function() {
        var currentScroll = window.pageYOffset || document.documentElement.scrollTop;
        if (currentScroll > scrollThreshold) {
            if (currentScroll > lastScroll) {
                header.classList.add('dimsop-header-hidden');
                header.classList.remove('dimsop-header-visible');
            } else {
                header.classList.remove('dimsop-header-hidden');
                header.classList.add('dimsop-header-visible');
            }
        } else {
            header.classList.remove('dimsop-header-hidden');
            header.classList.remove('dimsop-header-visible');
        }
        lastScroll = currentScroll;
    }, { passive: true });

    var progressBar = document.getElementById('dimsop-scroll-progress');
    if (progressBar) {
        window.addEventListener('scroll', function() {
            var scrollTop = window.pageYOffset || document.documentElement.scrollTop;
            var docHeight = document.documentElement.scrollHeight - document.documentElement.clientHeight;
            var scrollPercent = docHeight > 0 ? (scrollTop / docHeight) * 100 : 0;
            progressBar.style.width = scrollPercent + '%';
        }, { passive: true });
    }

    function getSections() {
        var arr = [];
        document.querySelectorAll('section[id]').forEach(function(section) {
            arr.push({
                id: section.id,
                el: section,
                offset: section.offsetTop - 120
            });
        });
        return arr;
    }

    function updateActiveLink() {
        var navLinks = document.querySelectorAll('.dimsop-nav .nav-link');
        var scrollPos = window.pageYOffset || document.documentElement.scrollTop;
        var current = '';
        var path = window.location.pathname;
        var sections = getSections();

        sections.forEach(function(section) {
            if (scrollPos >= section.offset) {
                current = section.id;
            }
        });

        var firstSectionId = sections.length > 0 ? sections[0].id : '';
        var sectionToNav = {
            'banner': '/', 'iso': '/', 'nosotros': '/#nosotros',
            'metodologia': '/#unidades', 'unidades': '/#unidades',
            'cobertura': '/#unidades', 'aliados': '/#aliados',
            'contadores': '/#unidades', 'proyectos': '/#unidades',
            'blog': '/blog', 'contacto': '/#contacto'
        };
        var activeHref = sectionToNav[current] || '/';

        navLinks.forEach(function(link) {
            link.classList.remove('dimsop-nav-active');
            var href = link.getAttribute('href') || '';

            if (path === '/blog' && href === '/blog') {
                link.classList.add('dimsop-nav-active');
            } else if (path === '/' && href === activeHref) {
                link.classList.add('dimsop-nav-active');
            }
        });
    }

    window.addEventListener('scroll', updateActiveLink, { passive: true });
    updateActiveLink();

    var wrap = document.getElementById('dimsop-search-wrap');
    if (wrap) {
        wrap.addEventListener('click', function(e) {
            if (e.target.tagName === 'INPUT') return;
            wrap.classList.toggle('dimsop-search-open');
            var input = wrap.querySelector('input');
            if (wrap.classList.contains('dimsop-search-open') && input) {
                input.focus();
            }
        });
        document.addEventListener('click', function(e) {
            if (!wrap.contains(e.target)) {
                wrap.classList.remove('dimsop-search-open');
            }
        });
    }

    var burger = document.getElementById('dimsop-burger-toggle');
    var mobileNav = document.getElementById('dimsop-mobile-nav');
    if (burger && mobileNav) {
        function closeMobileMenu() {
            mobileNav.classList.remove('dimsop-mobile-open');
            burger.classList.remove('dimsop-burger-active');
            burger.setAttribute('aria-expanded', 'false');
            mobileNav.setAttribute('aria-hidden', 'true');
        }

        burger.addEventListener('click', function() {
            var isOpen = mobileNav.classList.contains('dimsop-mobile-open');
            if (isOpen) {
                closeMobileMenu();
            } else {
                mobileNav.classList.add('dimsop-mobile-open');
                burger.classList.add('dimsop-burger-active');
                burger.setAttribute('aria-expanded', 'true');
                mobileNav.setAttribute('aria-hidden', 'false');
            }
        });

        mobileNav.querySelectorAll('.nav-link').forEach(function(link) {
            link.addEventListener('click', function() {
                closeMobileMenu();
            });
        });

        document.addEventListener('click', function(e) {
            if (!burger.contains(e.target) && !mobileNav.contains(e.target)) {
                closeMobileMenu();
            }
        });
    }

    document.querySelectorAll('a[href^="/#"]').forEach(function(anchor) {
        anchor.addEventListener('click', function(e) {
            var hash = this.getAttribute('href');
            if (hash) {
                var target = document.querySelector(hash);
                if (target) {
                    e.preventDefault();
                    var headerHeight = header.offsetHeight || 70;
                    var targetPosition = target.getBoundingClientRect().top + window.pageYOffset - headerHeight;
                    window.scrollTo({ top: targetPosition, behavior: 'smooth' });
                }
            }
        });
    });
})();

(function() {
    var prefersReducedMotion = window.matchMedia &&
        window.matchMedia('(prefers-reduced-motion: reduce)').matches;

    if (prefersReducedMotion) return;

    function loadGSAP(callback) {
        if (window.gsap && window.ScrollTrigger) { callback(); return; }
        var gsapScript = document.createElement('script');
        gsapScript.src = 'https://cdn.jsdelivr.net/npm/gsap@3.12.5/dist/gsap.min.js';
        gsapScript.onload = function () {
            var stScript = document.createElement('script');
            stScript.src = 'https://cdn.jsdelivr.net/npm/gsap@3.12.5/dist/ScrollTrigger.min.js';
            stScript.onload = function () {
                gsap.registerPlugin(ScrollTrigger);
                callback();
            };
            document.head.appendChild(stScript);
        };
        document.head.appendChild(gsapScript);
    }

    function initAnimations() {
        gsap.config({ nullTargetWarn: false });

        gsap.from('.dimsop-hero-eyebrow-text', {
            opacity: 0, letterSpacing: '8px', duration: 0.8, delay: 0.2, ease: 'power2.out'
        });
        gsap.from('.dimsop-hero-eyebrow-line', {
            scaleX: 0, opacity: 0, duration: 0.6, delay: 0.3, stagger: 0.1, ease: 'power2.out'
        });
        gsap.from('#banner h1', { y: 40, opacity: 0, duration: 1, delay: 0.5, ease: 'power3.out' });
        gsap.from('#banner .dimsop-lead', { y: 30, opacity: 0, duration: 1, delay: 0.7, ease: 'power3.out' });

        var nosotrosTl = gsap.timeline({
            scrollTrigger: { trigger: '#nosotros', start: 'top 75%', toggleActions: 'play none none reverse' }
        });
        nosotrosTl
            .from('#nosotros .dimsop-h2', { y: 40, opacity: 0, duration: 0.8, ease: 'power3.out' })
            .from('#nosotros .dimsop-lead', { y: 25, opacity: 0, duration: 0.7, ease: 'power3.out' }, '-=0.5')
            .from('#nosotros .col-lg-6:first-child .dimsop-card', { x: -60, opacity: 0, duration: 0.8, ease: 'power3.out' }, '-=0.3')
            .from('#nosotros .col-lg-6:last-child .dimsop-card', { x: 60, opacity: 0, duration: 0.8, ease: 'power3.out' }, '-=0.6')
            .from('#nosotros .dimsop-h3', { y: 30, opacity: 0, duration: 0.6, ease: 'power3.out' }, '-=0.3')
            .from('#nosotros .text-center.mb-4', { y: 20, opacity: 0, duration: 0.5, ease: 'power3.out' }, '-=0.4')
            .from('#nosotros .dimsop-value', { scale: 0.85, opacity: 0, duration: 0.5, stagger: 0.08, ease: 'back.out(1.4)' }, '-=0.3');

        gsap.from('#iso', {
            x: -60, opacity: 0, duration: 0.7, ease: 'power3.out',
            scrollTrigger: { trigger: '#iso', start: 'top 90%', toggleActions: 'play none none reverse' }
        });

        gsap.from('#metodologia .dimsop-h2', {
            y: 50, opacity: 0, duration: 0.8, ease: 'power3.out',
            scrollTrigger: { trigger: '#metodologia', start: 'top 80%', toggleActions: 'play none none reverse' }
        });
        gsap.from('#metodologia .dimsop-img-methodology', {
            scale: 0.95, opacity: 0, duration: 1, ease: 'power2.out',
            scrollTrigger: { trigger: '#metodologia .dimsop-img-methodology', start: 'top 85%', toggleActions: 'play none none reverse' }
        });
        gsap.from('#metodologia .dimsop-step', {
            y: 40, opacity: 0, duration: 0.6, stagger: 0.12, ease: 'power3.out',
            scrollTrigger: { trigger: '#metodologia .row', start: 'top 85%', toggleActions: 'play none none reverse' }
        });

        gsap.from('#unidades .dimsop-h2', {
            y: 50, opacity: 0, duration: 0.8, ease: 'power3.out',
            scrollTrigger: { trigger: '#unidades', start: 'top 80%', toggleActions: 'play none none reverse' }
        });
        gsap.from('#unidades .dimsop-card', {
            y: 40, opacity: 0, duration: 0.6, stagger: 0.18, ease: 'power3.out',
            scrollTrigger: { trigger: '#unidades .row', start: 'top 85%', toggleActions: 'play none none reverse' }
        });

        gsap.from('#cobertura .dimsop-h2', {
            y: 50, opacity: 0, duration: 0.8, ease: 'power3.out',
            scrollTrigger: { trigger: '#cobertura', start: 'top 80%', toggleActions: 'play none none reverse' }
        });
        gsap.fromTo('#cobertura .dimsop-map',
            { scale: 0.92, opacity: 0 },
            {
                scale: 1, opacity: 1, duration: 1, ease: 'power2.out',
                scrollTrigger: { trigger: '#cobertura .dimsop-map', start: 'top 85%', toggleActions: 'play none none reverse' },
                onComplete: function() { gsap.set(this.targets(), { clearProps: 'transform,opacity' }); },
                onReverseComplete: function() { gsap.set(this.targets(), { clearProps: 'transform,opacity' }); }
            }
        );

        gsap.from('#aliados .dimsop-h2', {
            y: 50, opacity: 0, duration: 0.8, ease: 'power3.out',
            scrollTrigger: { trigger: '#aliados', start: 'top 80%', toggleActions: 'play none none reverse' }
        });

        var contadoresTl = gsap.timeline({
            scrollTrigger: {
                trigger: '#contadores',
                start: 'top 80%',
                toggleActions: 'play none none reverse'
            }
        });
        contadoresTl.from('.dimsop-counter-box', {
            scale: 0.85, opacity: 0, duration: 0.6,
            stagger: 0.2, ease: 'back.out(1.7)'
        });
        contadoresTl.from('.dimsop-counter p', {
            y: 20, opacity: 0, duration: 0.5,
            stagger: 0.2, ease: 'power2.out'
        }, '-=0.3');
        document.querySelectorAll('.dimsop-counter-num[data-target]').forEach(function(el) {
            var target = parseInt(el.getAttribute('data-target'), 10);
            var prefix = el.textContent.trim().charAt(0) === '+' ? '+' : '';
            var proxy = { val: 0 };
            contadoresTl.to(proxy, {
                val: target,
                duration: 1.8,
                ease: 'power2.out',
                onUpdate: function() {
                    el.textContent = prefix + Math.floor(proxy.val);
                }
            }, 0);
        });

        gsap.from('#proyectos .dimsop-h2', {
            y: 50, opacity: 0, duration: 0.8, ease: 'power3.out',
            scrollTrigger: { trigger: '#proyectos', start: 'top 80%', toggleActions: 'play none none reverse' }
        });

        gsap.from('#blog .dimsop-h2', {
            y: 50, opacity: 0, duration: 0.8, ease: 'power3.out',
            scrollTrigger: { trigger: '#blog', start: 'top 80%', toggleActions: 'play none none reverse' }
        });
        gsap.from('#blog .dimsop-blog-card', {
            y: 30, opacity: 0, duration: 0.6, stagger: 0.12, ease: 'power3.out',
            scrollTrigger: { trigger: '#blog .row', start: 'top 85%', toggleActions: 'play none none reverse' }
        });

        gsap.from('#contacto .dimsop-h2', {
            y: 50, opacity: 0, duration: 0.8, ease: 'power3.out',
            scrollTrigger: { trigger: '#contacto', start: 'top 80%', toggleActions: 'play none none reverse' }
        });
        gsap.from('#contacto .dimsop-form', {
            y: 30, opacity: 0, duration: 0.7, ease: 'power3.out',
            scrollTrigger: { trigger: '#contacto .dimsop-form', start: 'top 85%', toggleActions: 'play none none reverse' }
        });

        gsap.from('#dimsop_footer .col-lg-4', {
            y: 30, opacity: 0, duration: 0.6, stagger: 0.12, ease: 'power3.out',
            scrollTrigger: { trigger: '#dimsop_footer', start: 'top 90%', toggleActions: 'play none none reverse' }
        });
    }

    loadGSAP(initAnimations);
})();

(function() {
    try {
        var t = localStorage.getItem('dimsop-theme');
        if (t === 'dark') document.documentElement.setAttribute('data-theme', 'dark');
    } catch(e) {}
})();

document.addEventListener('DOMContentLoaded', function() {
    var btn = document.getElementById('dimsop-dark-toggle');
    if (!btn) return;
    btn.addEventListener('click', function() {
        var isDark = document.documentElement.getAttribute('data-theme') === 'dark';
        var next = isDark ? 'light' : 'dark';
        document.documentElement.setAttribute('data-theme', next);
        try { localStorage.setItem('dimsop-theme', next); } catch(e) {}
        var icon = btn.querySelector('i');
        if (icon) {
            icon.className = next === 'dark' ? 'fa fa-sun-o' : 'fa fa-moon-o';
        }
    });
    var icon = btn.querySelector('i');
    if (icon && document.documentElement.getAttribute('data-theme') === 'dark') {
        icon.className = 'fa fa-sun-o';
    }
});
